function scrollToY(e){window.scrollTo({top:e,behavior:"smooth"})}window.addEventListener("load",function(){let o=document.querySelector(".page-header"),n=document.querySelectorAll(".animation-up"),l=document.querySelectorAll(".animation-left"),a=document.querySelectorAll(".animation-right");scrollToY(0),window.addEventListener("scroll",function(e){72<window.pageYOffset?o.classList.add("page-header__scroll"):o.classList.remove("page-header__scroll");let t=window.innerHeight;n.forEach(e=>{e.getBoundingClientRect().top<t-210&&(e.style.opacity="1",e.style.transform="translateY(0)")}),l.forEach(e=>{e.getBoundingClientRect().top<t-210&&(e.style.opacity="1",e.style.transform="translateX(0)")}),a.forEach(e=>{e.getBoundingClientRect().top<t-210&&(e.style.opacity="1",e.style.transform="translateX(0)")})})});